-- Let me check how many devices each formula would return with > 7.5 threshold
-- Formula 1: (battlifeh * battcapmah) / (chgtimemin * pwractmw)
SELECT count(*) as cnt_formula1 FROM testsessions t JOIN deviceidentity d ON t.sessionregistry = d.devsessionref WHERE t.battlevel > 0 AND t.chgtimemin > 0 AND d.pwractmw > 0 AND (t.battlifeh * t.battcapmah::numeric) / (t.chgtimemin * d.pwractmw) > 7.5;

-- Formula 2: battlifeh * battlevel / chgtimemin / 10
SELECT count(*) as cnt_formula2 FROM testsessions t WHERE t.battlevel > 0 AND t.chgtimemin > 0 AND (t.battlifeh * t.battlevel::numeric / t.chgtimemin / 10) > 7.5;
